const run = $node["运行Runner"].json;
const journalWrap = $node["获取RunJournal"].json;
const journal = journalWrap?.journal || null;

const marketText = $node["读取市场成交额文件"].json?.text || '';
const etfText = $node["读取ETF成交额文件"].json?.text || '';

const iconMap = { success: '✅', partial: '⚠️', failed: '❌' };
const icon = iconMap[run.status] || '❓';

const asOfStr = String(run.asOf || '');
const asOf = asOfStr.includes('T') ? asOfStr.split('T')[1].slice(0,5) : '15:00';

let market = null;
try {
  const lines = marketText.split('\n').map(s => s.trim()).filter(Boolean);
  const last = JSON.parse(lines[lines.length - 1]);
  market = Number(last.total ?? last.total_amount ?? 0);
} catch (e) {
  market = null;
}

let etfD = null;
try {
  const lines = etfText.split('\n').map(s => s.trim()).filter(Boolean);
  const last = JSON.parse(lines[lines.length - 1]);
  if (Array.isArray(last)) etfD = Number(last[1] || 0);
  else etfD = Number(last.total ?? last.amount ?? 0);
} catch (e) {
  etfD = null;
}

const etfM = etfD != null && Number.isFinite(etfD) && etfD > 0 ? 'OK' : 'NA';
let share = null;
if (market != null && etfD != null && Number.isFinite(market) && Number.isFinite(etfD) && market > 0) {
  share = ((etfD / market) * 100).toFixed(2);
}

let failStep = 'None';
let err = 'None';
if (journal && Array.isArray(journal.steps)) {
  const failed = journal.steps.find(s => s.status === 'failed');
  if (failed) {
    failStep = failed.name;
    err = failed.error?.message || (failed.warnings || []).find(w => w.severity === 'error')?.message || 'failed';
  } else {
    const merge = journal.steps.find(s => s.name === 'amount_merge');
    const outs = (merge?.outputs || []).map(o => o.path).filter(Boolean);
    const need = [
      `data/market/market-amount-daily.jsonl`,
      `data/m0/${run.day}/${run.runId}/etf_amount_minute.jsonl`,
      `data/m0/${run.day}/${run.runId}/etf_amount_daily.jsonl`,
    ];
    const missing = need.filter(p => !outs.includes(p));
    if (missing.length > 0) {
      failStep = 'amount_merge';
      err = 'Missing outputs: ' + missing.join(', ');
    }
  }
}

const line1 = `M0-A ${icon} day=${run.day} asOf=${asOf}`;
const line2 = `market=${market ?? 'NA'} etfD=${etfD ?? 'NA'} etfM=${etfM} share=${share ?? 'NA'}%`;
const line3 = `out: amounts.json + etf_minute + etf_daily (failStep=${failStep} err=${err})`;

return [{ line1, line2, line3, summary: `${line1}\n${line2}\n${line3}` }];
